echo "== 3.33 (part B, X4): build_from_html recognises a map, a counter and accordion and tab markup"
# the markup X4 saw stay a Custom HTML element and text: a map frame, a data-counter paragraph; and the ARIA accordion and tabs
C333_HTML='<section class=\"c333\"><h2>Visit us</h2><iframe src=\"https://maps.google.com/maps?q=Mill%20Lane%203%2C%20Oxford&z=15&output=embed\"></iframe><div class=\"stat\"><p data-counter=\"250\">250+</p><p>completed projects</p></div></section><section><div class=\"faq\"><button aria-controls=\"q1\">How long?</button><div id=\"q1\" hidden><p>Six weeks.</p></div></div><div class=\"tabs\"><div role=\"tablist\"><button role=\"tab\" aria-controls=\"p1\">Oak</button><button role=\"tab\" aria-controls=\"p2\">Ash</button></div><div role=\"tabpanel\" id=\"p1\"><p>Warm.</p></div><div role=\"tabpanel\" id=\"p2\" hidden><p>Light.</p></div></div></section>'
mcp build_from_html "{\"title\":\"X4 widgets 333\",\"html\":\"$C333_HTML\"}" > "$WORK/response"; mcp_text
C333_PAGE=$(sq "SELECT ids FROM ka_stranky WHERE titulek = 'X4 widgets 333' AND smazano IS NULL")
C333_TYPES=$("${MYSQL[@]}" --default-character-set=utf8mb4 "$DB_NAME" -N -r -e "SELECT IFNULL(stavba_koncept, stavba) FROM ka_stranky WHERE ids = $C333_PAGE" | php -r '$b = json_decode(stream_get_contents(STDIN), true); $t = []; $w = function ($n) use (&$w, &$t) { foreach ($n as $p) { if (!in_array($p["typ"], ["sekce", "kontejner"], true)) { $t[] = $p["typ"]; } $w($p["deti"] ?? []); } }; $w($b["deti"] ?? []); echo implode(",", $t);')
expect "3.33 X4: build_from_html – the map frame is a Map element, data-counter a Counter, the ARIA accordion an FAQ, role=tab Tabs; the notes say so" \
  "$C333_TYPES|$(php -r '$r = json_decode(file_get_contents($argv[1]), true); echo count(array_filter($r["notes"] ?? [], fn ($n) => (bool) preg_match("/^(A map became a Map element \(Mill Lane 3, Oxford\)|A counter became a Counter element \(250\)|An accordion became an FAQ element|Tabs became a Tabs element)/", $n)));' "$WORK/text")" \
  "nadpis,mapa,pocitadlo,faq,zalozky|4"
